# LAYER 1 - gentle chords
# Chord loop: Ebmaj7 -> Cm7 -> Abmaj7 -> Bb(add9)

chords = [
    [51, 58, 62, 55],   # Ebmaj7
    [48, 55, 58, 51],   # Cm7
    [44, 51, 55, 48],   # Abmaj7
    [46, 53, 60, 50],   # Bb(add9)
]

for cycle in range(2):
    for c in range(len(chords)):
        if cycle == 1 and c == 3:
                for note in chords[c]:
                    playNote(note, beats = 1.5)
                    rest(beats = 0.5)
        if cycle == 0 and c == 0:
                for note in chords[c]:
                    playNote(note, beats = 1.5)
                    rest(beats = 0.5)
        else:
                for note in chords[c]:
                    playNote(note, beats = 1.5)
                    rest(beats = 0.5)
